/* Per-game configuration: see gamecfg.h. */
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include "gamecfg.h"
#include "platform.h"
#include "runtime.h"
#include "gamecfg_embedded.h"   /* generated by CMake: static const char g_game_ini[] */

typedef struct { char *section, *key, *value; } Entry;
static Entry *g_ent;
static int g_n, g_cap;

static char *trim(char *s) {
    while (isspace((unsigned char)*s)) s++;
    char *e = s + strlen(s);
    while (e > s && isspace((unsigned char)e[-1])) *--e = 0;
    return s;
}

static void parse(const char *text, const char *origin) {
    char section[64] = "";
    const char *p = text;
    int lineno = 0;
    while (*p) {
        const char *nl = strchr(p, '\n');
        size_t len = nl ? (size_t)(nl - p) : strlen(p);
        char line[1024];
        if (len >= sizeof line) len = sizeof line - 1;
        memcpy(line, p, len);
        line[len] = 0;
        p += len + (nl ? 1 : 0);
        lineno++;
        char *c = strpbrk(line, "#;");
        if (c && (c == line || isspace((unsigned char)c[-1]))) *c = 0;
        char *s = trim(line);
        if (!*s) continue;
        if (*s == '[') {
            char *e = strchr(s, ']');
            if (e) { *e = 0; snprintf(section, sizeof section, "%s", trim(s + 1)); }
            continue;
        }
        char *eq = strchr(s, '=');
        if (!eq) { rt_log("%s:%d: ignored line \"%s\"", origin, lineno, s); continue; }
        *eq = 0;
        if (g_n == g_cap) {
            g_cap = g_cap ? g_cap * 2 : 64;
            g_ent = realloc(g_ent, sizeof *g_ent * (size_t)g_cap);
        }
        g_ent[g_n++] = (Entry){strdup(section), strdup(trim(s)), strdup(trim(eq + 1))};
    }
}

void cfg_init(void) {
    parse(g_game_ini, "built-in game.ini");
    char path[1200];
    snprintf(path, sizeof path, "%s/game.ini", platform_save_dir());
    FILE *f = fopen(path, "rb");
    if (!f) return;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = calloc(1, (size_t)n + 1);
    if (fread(buf, 1, (size_t)n, f) == (size_t)n) {
        /* An override replaces whole repeated lists (e.g. all buttons) when it
         * defines that key at all, so drop the built-in ones first. */
        int before = g_n;
        parse(buf, path);
        for (int i = before; i < g_n; i++)
            for (int j = 0; j < before; j++)
                if (g_ent[j].key[0] && !strcasecmp(g_ent[j].section, g_ent[i].section) &&
                    !strcasecmp(g_ent[j].key, g_ent[i].key))
                    g_ent[j].key[0] = 0;
        rt_log("read %s", path);
    }
    free(buf);
    fclose(f);
}

static const Entry *find_last(const char *section, const char *key) {
    for (int i = g_n - 1; i >= 0; i--)
        if (!strcasecmp(g_ent[i].section, section) && !strcasecmp(g_ent[i].key, key)) return &g_ent[i];
    return NULL;
}

const char *cfg_str(const char *section, const char *key, const char *def) {
    const Entry *e = find_last(section, key);
    return e ? e->value : def;
}

int cfg_int(const char *section, const char *key, int def) {
    const Entry *e = find_last(section, key);
    return e && *e->value ? (int)strtol(e->value, NULL, 0) : def;
}

/* every key of a section, in file order */
void cfg_each_line(const char *section, void (*fn)(const char *key, const char *value, void *ctx), void *ctx) {
    for (int i = 0; i < g_n; i++)
        if (!strcasecmp(g_ent[i].section, section)) fn(g_ent[i].key, g_ent[i].value, ctx);
}

void cfg_each(const char *section, const char *key, void (*fn)(const char *, void *), void *ctx) {
    for (int i = 0; i < g_n; i++)
        if (!strcasecmp(g_ent[i].section, section) && !strcasecmp(g_ent[i].key, key)) fn(g_ent[i].value, ctx);
}

static const struct { const char *name; int vk; } VK_NAMES[] = {
    {"BACKSPACE", 0x08}, {"TAB", 0x09}, {"ENTER", 0x0d}, {"RETURN", 0x0d}, {"SHIFT", 0x10},
    {"CTRL", 0x11}, {"CONTROL", 0x11}, {"ALT", 0x12}, {"MENU", 0x12}, {"PAUSE", 0x13},
    {"CAPSLOCK", 0x14}, {"ESC", 0x1b}, {"ESCAPE", 0x1b}, {"SPACE", 0x20}, {"PGUP", 0x21},
    {"PGDN", 0x22}, {"END", 0x23}, {"HOME", 0x24}, {"LEFT", 0x25}, {"UP", 0x26}, {"RIGHT", 0x27},
    {"DOWN", 0x28}, {"INSERT", 0x2d}, {"DELETE", 0x2e}, {"LSHIFT", 0xa0}, {"RSHIFT", 0xa1},
    {"LCTRL", 0xa2}, {"RCTRL", 0xa3}, {"LALT", 0xa4}, {"RALT", 0xa5},
    {"NUM0", 0x60}, {"NUM1", 0x61}, {"NUM2", 0x62}, {"NUM3", 0x63}, {"NUM4", 0x64},
    {"NUM5", 0x65}, {"NUM6", 0x66}, {"NUM7", 0x67}, {"NUM8", 0x68}, {"NUM9", 0x69},
    {"MULTIPLY", 0x6a}, {"ADD", 0x6b}, {"SUBTRACT", 0x6d}, {"DIVIDE", 0x6f},
    {"CHEATS", PORT_VK_CHEATS}, /* port action: opens the cheat menu (cheatmenu.c) */
};

int cfg_vk(const char *s) {
    if (!s || !*s) return 0;
    if (!s[1] && isalnum((unsigned char)s[0])) return toupper((unsigned char)s[0]); /* a letter or digit key */
    if (isdigit((unsigned char)s[0])) return (int)strtol(s, NULL, 0) & 0xff;
    if (toupper((unsigned char)s[0]) == 'F' && isdigit((unsigned char)s[1])) {
        int n = atoi(s + 1);
        if (n >= 1 && n <= 24) return 0x6f + n;
    }
    for (size_t i = 0; i < sizeof VK_NAMES / sizeof VK_NAMES[0]; i++)
        if (!strcasecmp(s, VK_NAMES[i].name)) return VK_NAMES[i].vk;
    rt_log("game.ini: unknown key name \"%s\"", s);
    return 0;
}

int cfg_vk_list(const char *s, int *out, int max) {
    int n = 0;
    char buf[256];
    snprintf(buf, sizeof buf, "%s", s ? s : "");
    for (char *t = strtok(buf, " \t,"); t && n < max; t = strtok(NULL, " \t,")) {
        int vk = cfg_vk(t);
        if (vk) out[n++] = vk;
    }
    return n;
}
